INSERT OR IGNORE INTO works (
  title, slug, issue_number, host_name, guest_name, excerpt, content_html,
  cover_key, audio_key, audio_original_name, status, published_at
) VALUES (
  '四项大奖背后的服务密码——售后品质团队的实战方法论',
  'vol-01',
  'Vol.01',
  '程帅杰',
  '操春林',
  'FFC售后品质团队连续三年蝉联"杰出服务支持奖"并斩获四项大奖的故事，揭秘团队在全球售后服务、质量改进、培训赋能方面的实战方法论',
  '<p>名扬海外Vol.01| 售后品质团队的实战方法论<br>受访对象：操春林（外销售后负责人）<br>访谈时间：09.28<br>________________________________________<br>大家好，欢迎来到名扬海外。今天非常荣幸邀请到我们的海外销售售后负责人操春林——操老师。在今年MIB全球峰会上，操老师的售后团队一举斩获4项大奖，连续3年蝉联杰出服务支持奖，同时拿下了最佳质量改善团队奖、质量投诉解决卓越团队奖、杰出培训奖和个人奖。首先恭喜团队能够获得这样的成绩！<br>________________________________________<br>Q:请您先做个自我介绍，也跟大家聊聊咱们售后团队到底是做什么的，很多同事呢可能还对这个岗位不太了解。<br>A:大家好，我是操春林，现在是咱们FFC团队外销售后的负责人。我们外销售后其实是2020年成立的一个比较新的模块。售后这个模块，其实很多人搞不清楚，主要原因就是会把它和品质搞混。我们售后更主要的是做一些技术支持类的工作，比如售后备件的订单、爆炸图、维修手册。而品质客诉类的工作，一般是由品质团队的市场品质部门对接，所以也借这个机会给大家再讲一下。</p><p>Q:操老师这次一口气拿了4个奖，尤其是连续3年蝉联了杰出服务支持奖，真的很不容易。您能跟大家分享一下团队是做对了什么，能够连续3年拿到这个奖？<br>A:我觉得这个事情分为两方面吧。第一个就是我之前常说的叫纲举目张，一定要首先明确整个团队的工作方向和工作目标，这个非常重要。我们海外售后刚成立的时候，在22年、23年连续两次组织了管委会的报告，根据管委会报告的结果，我们去做了维修手册、售后数据、售后备件，包括海外当地的售后支持政策等各方面的一些规划。然后后面所做的事情就是按照这个规划去执行，所以这个很重要，就是纲举目张，一定要先明确目标和各个部门协同做事的方法。第二个的话我觉得比较重要的事情就是资源的配置。我们售后的团队从20年一个人光杆司令到现在，洗衣机加清洁十几号人，可以说是从无到有、一步一步走过来。我们现在建立了比较完善的售后技术支持、售后备件订单交付、海外售后培训，这样几个功能模块，每个模块职责清晰，人员能力配置也都基本到位。<br>在这个过程中也不是一蹴而就的，也是分了好多年，每一年逐步增强一点，每一年逐步增强一点。先做好技术支持部分，去接了售后备件相关的活儿，然后配置了相关的组织和人员；再往后就是增加了售后培训的功能和模块，也配置了相应的专职培训讲师。每一个人资源配置到位了以后，发挥他们的特长，在这个领域之内培养他们做到最好，这样子的话整个团队的战斗力也会很强。所以我觉得我们能够获奖主要也就这两方面，第一个纲举目张，第二个配置合适的资源，最后大家按照这个目标去努力。</p><p>Q:说实话，售后服务这个岗位很多时候可能都是背锅的角色，比如说产品出了问题，客户第一个骂的可能就是我们。您觉得做这个岗位的最大挑战是什么？<br>A:最大的挑战可能就是做售后就要处理一些可能不是我们职权范围之内的问题，这个就会涉及到一些跨部门的沟通协调以及问题的上升。我的经验就是有问题一定要跳出来，不要自己藏着掖着，搞不定的东西越早跳出来越好。</p><p>Q:那有没有感觉哪个时刻让你觉得特别深刻，比如说遇到了什么质量问题啊，然后自己去售后处理这些？<br>A:这个就太多了，可能有听说过的同事知道的，比如说德国能效打官司的事情，比如说美国DOE的事情，比如说巴西滚筒召回的事情，各种各样奇奇怪怪的事，大家如果有兴趣来找我私聊。</p><p>Q:面对这些挑战，团队有什么核心的方法论，比如说遇到了投诉，我们有没有一套标准化的流程或者独门秘籍，能够既快速解决问题又能让客户满意？<br>A:质量投诉这个东西的话，其实所有的业务员也应该知道一个基础。我之前给所有的海外业务、所有的新人都要上的一个培训叫做海外售后品质基础。这个培训当中就会提到说客诉我们需要解决一个东西，方法论其实非常简单，现在也可以给大家讲一下。品质内部或者是研发内部会有一个叫做DMAIC或者PDCA的整个一套方法论，整个成熟的集团层面的话，精益制造的一套方法体系也会提到说8D。对外客诉我个人是比较建议使用8D这套方法，从问题的明确、原因的分析、短期的围堵措施、根因的分析、根因的改善水平展开，然后一直到最后的经验总结、方法固化，整个是有一套非常成熟的方法论。大家遇到问题的时候也要按这个思路去处理，不光是品质问题，任何问题其实遇到的都是这样子，先搞清楚发生了什么，原因是什么，然后怎么解决，解决完了以后怎么固化，后面让它不要再犯，方法其实都是一样的。</p><p>Q:售后服务不是孤军奋战，经常需要跟前线业务和产品研发、供应链等多个部门协同，在实际工作中如何能够跟这些部门高效配合，有没有什么经验可以分享给其他同事？<br>A:官方说法就是一定要跨部门沟通、领导支持，还有个人魅力。然后私底下说点干货的话，就是你一定要跟其他部门有利益往来的地方，你帮他解决他的问题，他才会帮你解决你的问题，相互之间是一个互帮的关系。私人关系当然很重要，但更多时候大家常说的叫屁股决定脑袋。我是这么认为的，就是你提出的这个问题，或者说你提出让他去干的这个事儿，对他来说他有什么收益，一定要把这个先想清楚。有的时候是正收益，有的时候是负收益，能够减少他的投诉，对他来说也是一种变相的正收益。</p><p>Q:咱们售后团队覆盖全球，不同区域的售后需求肯定不一样，比如说中东、拉美、欧洲这些客户，他们的需求有什么差异，然后咱们的售后团队如何能够做到因地制宜？<br>A:这个就比较有意思了，这个可以展开来仔细讲一讲。<br>不同区域我常说的一句话叫做各个国家都自有国情，特别好玩。比如说咱们中东业务应该都知道，大家互相喊brothers是吧？你跟他是brothers，很多事都好说；你要跟他一板一眼地去较真，很多事情就变得不上秤没四两重、上了秤千斤重，人家就跟你开始较真，然后就会把事情变得很大。但是你去了欧美，人家又是一本正经的一整套的东西。你去了跟欧洲大客户谈，我觉得除了最基本的一些信任和人情的一些沟通以外，一切沟通和处理事情的基础是双方的合同和法律，合同怎么签的我们就怎么做。所以这也是我们一直说跟客户开始建立合作的时候，一定要签一份框架合作协议，然后这份协议的内容尽量使用美的的标准内容，这个非常重要，有了合同才有后面做所有事情的基础。<br>欧美的风格都是这样，就是从合同出发，然后再叠加人情，人情和关系只能居其次，合同是基础，但是其他的地方你去跟中东的哥们谈我们签合同吧，很有可能人家给几个大白眼。<br>Q:拉美呢？<br>A:拉美不同国家差别非常大，拉美你可以认为它是一个综合体。它会有欧美的法律体系，比如阿根廷、巴西，包括智利，他们其实祖上阔过，1900年的时候布宜诺斯艾利斯号称是拉美小巴黎，祖上阔过，他们的法律体系、整个基础建设、整个制度其实很完善。但是现在可能由于各种各样的原因，我们说的中等收入陷阱或者拉美陷阱之类的，他们国家现在整个情况可能跟欧美有些区别。<br>但是大家记住，跟我们打交道的都是相对来说比较高阶层的人士，比较高级的，你可以把他们当做欧美人。所以拉美就是一个有着严谨的法律体系和相对完善的社会治理体系、社会运转机制，但是可以谈人情、可以变通的复杂社会。很多时候在拉美的话，规矩是规矩，做事是做事。</p><p>Q:如果说有同事想加入咱们售后的团队，或者想在这个岗位上做得更好，您最想给他什么建议？<br>A:我觉得核心的一个东西就是定位。第一个事情就是大家一定要想，这是一个后台支持部门，相比业务来说更偏后端，所以风光的机会、上台领奖的机会或者是领导表扬的机会其实不会那么多。但是这个职位会很锻炼人，因为你要处理各种各样的问题，你要跟所有的内部的、外部的人去打交道，然后对综合能力的要求其实也是蛮高的。如果想在这个岗位上做好，最主要的就是刚刚最开始说方法论的时候提到的，我一直认为是遇到事情不要着急，先搞清楚发生了什么。我们内部的研发、品质，包括我们很多业务，很多时候有一个很大的问题，就是遇到事情先着急，先着急着去安抚客户，或者说回复客户，给客户一个改善方案也好，控制对策也好，但其实最重要的事情是你搞清楚发生了什么，问题是什么。<br>问题是什么永远是第一步。如果大家感兴趣的话可以去搜一下，就是一些质量控制手册或者是精益管理相关的书。对于问题的定义，就比如说DMAIC的第一阶段或者是8D的第二第三阶段，问题的定义是一个科学的、一整套的方法体系，一定要讲清楚。我们内部培训的时候，其实经常说什么5Why或者什么4W1H之类的东西，时间、地点、人物，以前小时候记叙文也常说的。你把这些东西一定要讲清楚：什么时间、什么机型、什么客户、在什么地方发生了什么事情，这个事情引发了后面的什么事情，后来又发生了什么事情，最后现在到了这个地方，我们现在客户的核心诉求是什么，一定要先搞清楚。我们作为业务的话，天生的职责就是搞清楚业务，搞清楚客户要什么，作为沟通的桥梁对内去传达，然后把内部收集到的所有的东西，整理规范以后再传递给客户。业务是一个对接的窗口，要有自己的思想，不是说照单全收。搞清楚发生了问题，搞清楚客户的要求，搞清楚客户到底要什么，是最重要的。</p><p>Q:最后一个问题，您可以用一句话来定义咱们售后团队的价值，或者说您的工作理念？<br>A:我觉得我们团队的价值就是做好后台所有的服务，让销售无后顾之忧，产品卖出去了以后，所有的售后问题全部能搞定。<br>________________________________________<br>好的，非常感谢操老师今天的分享，4项大奖的背后是团队持续深耕服务质量，培训赋能质量改进的结果。相信通过今天的访谈，大家对咱们的售后团队有了更深入的了解，也学到了很多可复用的经验。再次恭喜操老师的售后团队，也希望未来能够看到更多这样的精彩故事！</p>',
  NULL,
